/// Load the editable profile fields not carried on the auth `User` row loader
/// (`display_name`, `bio`, `created_at`, `must_change_password`). Falls back to
/// empties on any lookup failure so building a session never fails on a cold profile.
async fn user_profile_fields(
    pool: &Database,
    user_id: &str,
) -> (Option<String>, Option<String>, String, bool) {
    let Ok(user_id) = crate::db_types::uuid(user_id) else {
        return (None, None, String::new(), false);
    };
    crate::db_types::query_tuple::<(Option<String>, Option<String>, String, bool)>(
        "SELECT display_name, bio, created_at, must_change_password FROM users WHERE id = $1",
    )
    .bind(user_id)
    .fetch_optional(pool)
    .await
    // Log (don't swallow) DB errors; still fall back to empties gracefully.
    .inspect_err(
        |e| tracing::warn!(error = %e, user_id = %user_id, "user_profile_fields query failed"),
    )
    .ok()
    .flatten()
    .unwrap_or((None, None, String::new(), false))
}

/// Build the client-facing `SessionUser` for a resolved auth `User`, loading its
/// profile fields. Every session-returning path funnels through this so the
/// shape stays consistent.
async fn build_session_user(pool: &Database, u: &User, show_nsfw: bool) -> SessionUser {
    let (display_name, bio, joined_at, must_change_password) =
        user_profile_fields(pool, &u.id).await;
    SessionUser {
        id: ID(u.id.clone()),
        username: u.username.clone(),
        display_name,
        bio,
        avatar_url: u.avatar_url.clone(),
        is_admin: u.is_admin != 0,
        show_nsfw,
        joined_at,
        must_change_password,
    }
}

/// Record one entry in a user's activity feed. Best-effort: a failed insert is
/// logged and swallowed so it can never fail the user's actual action (posting
/// a review/comment, adding to the library).
async fn log_activity(
    pool: &Database,
    user_id: &str,
    kind: &str,
    target_type: Option<&str>,
    target_id: Option<&str>,
) {
    let Ok(user_id) = crate::db_types::uuid(user_id) else {
        return;
    };
    let res = sqlx::query(
        "INSERT INTO user_activity (id, user_id, kind, target_type, target_id, created_at) \
         VALUES ($1, $2, $3, $4, $5, $6)",
    )
    .bind(uuid::Uuid::new_v4())
    .bind(user_id)
    .bind(kind)
    .bind(target_type)
    .bind(target_id)
    .bind(Utc::now())
    .execute(pool)
    .await;
    if let Err(e) = res {
        crate::db::record_database_error(&e);
        tracing::warn!(error = %e, kind, "failed to record user activity");
    }
}

// ---- Catalogue / dedup (CATALOGUE.md §4, §6) -------------------------------

/// Outcome of running the dedup matcher for a newly-added Tier-2 source series.
/// `decision` is one of `auto_merge` | `review` | `new`.
#[derive(SimpleObject)]
pub struct MatchResult {
    pub decision: String,
    /// The canonical work the series was linked to (its own new work for `new`).
    pub work_id: String,
    /// The matched canonical work (for `auto_merge` / `review`); absent for `new`.
    pub matched_work_id: Option<String>,
    pub score: Option<f64>,
    pub method: Option<String>,
    pub source_series_id: String,
}

/// One row of the canonical updates feed: a mirrored MangaDex work with its most
/// recent stored chapter (CATALOGUE.md §6). Served from the `chapter` mirror, not a
/// live Suwayomi round-trip. `work_id` opens the work through the canonical reader
/// path (`canonicalSeries`); `cover_url` is a proxy-ready MangaDex cover thumbnail.
#[derive(SimpleObject, sqlx::FromRow)]
pub struct CanonicalUpdate {
    #[sqlx(skip)]
    pub average_rating: Option<f64>,
    #[sqlx(skip)]
    pub rating_count: i32,
    #[sqlx(try_from = "crate::db_types::DbString")]
    pub work_id: String,
    #[sqlx(try_from = "crate::db_types::DbString")]
    pub mangadex_id: String,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    pub title: Option<String>,
    pub is_nsfw: bool,
    /// Proxy-ready cover thumbnail URL (`uploads.mangadex.org`), or null if the cover
    /// fileName hasn't been synced yet. The client resolves it through the Worker.
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    pub cover_url: Option<String>,
    /// Latest stored chapter number (string — chapters can be "10.5").
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    pub latest_chapter: Option<String>,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    pub latest_chapter_title: Option<String>,
    /// Publish time of the latest stored chapter (falls back to ingest time).
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    pub latest_at: Option<String>,
}

/// One row of the reader's merged Updates feed (`updatesFeed`), read from the
/// materialized `feed_series_updates` table (migration 0064).
///
/// Declared here rather than in `types.rs` alongside `SeriesPage`, next to the other
/// feed/catalogue objects `mod.rs` already owns (`CanonicalUpdate`, `MatchResult`,
/// `MergeQueuePage`) — it pairs with the resolver and the `FeedSeriesUpdateRow` mapping
/// below, which is where every question about it gets answered.
///
/// It is deliberately NOT a `Series`: the feed is 48k rows and a `Series` costs several
/// per-row lookups to assemble, while the grid renders six scalars. `id` is the
/// READER-OPENABLE id — a `w_…` canonical work id when the work is MangaDex-anchored,
/// else the numeric Suwayomi series id — so the card's link works either way (see the
/// `reader_id` note in the migration).
#[derive(SimpleObject, Clone)]
pub struct UpdateFeedRow {
    pub id: ID,
    /// The canonical work this row is one-per-of; the feed's dedupe key. Distinct from
    /// `id` for a Suwayomi-only work.
    pub work_id: String,
    pub title: String,
    pub cover_url: Option<String>,
    /// Effective format, materialized at refresh time so the format facet is a server
    /// filter over the whole feed rather than over the 20 rows of one page.
    pub r#type: Option<ComicType>,
    /// The work's publication status, materialized on `feed_series_updates` by migration
    /// 0068 (normalized to this enum's vocabulary at WRITE time — see the migration's
    /// `ON_HIATUS`/`PUBLISHING_FINISHED` fold). Pure cache, rewritten wholesale by the
    /// catalog refresh; the card renders it through the reader's `STATUS_META`.
    pub status: Option<SeriesStatus>,
    /// Chapter NUMBER of the newest mirrored chapter ("10.5"); null on scanner-only rows.
    pub latest_chapter: Option<String>,
    pub latest_chapter_title: Option<String>,
    /// Total chapters known for the series; null on mirror-only rows. The reader labels
    /// `Ch. {latestChapter ?? chapterCount}`, which is what each half already showed.
    pub chapter_count: Option<i32>,
    /// The real upstream release time of the newest chapter, ISO-8601 — what the SOURCE
    /// says. No longer the sort key (see [`Self::announced_at`]); still the honest answer
    /// to "when did this chapter come out", which is what the card's detail line reports.
    pub released_at: String,
    /// When this chapter first became something we could show anyone — ISO-8601, from
    /// `feed_series_updates.announced_at` (migration 0099). **THE sort key of this feed**,
    /// and therefore the instant the card's primary label must print, so the visible order
    /// and the visible label agree.
    ///
    /// Differs from [`Self::released_at`] only where a source held a chapter back: early
    /// access, a paywall, a regional delay. Equal to it everywhere else, and equal to it on
    /// every row recorded before 0099 — so a client that renders
    /// `announcedAt ?? releasedAt` is correct in every state, including against a server
    /// that predates this field.
    ///
    /// NOT the same as [`Self::detected_at`], which is `series_scan_state
    /// .last_new_chapter_at`: that is per-SERIES, Suwayomi-only, and never stamped on a
    /// baseline scan. This is per-CHAPTER and covers both halves of the catalogue.
    pub announced_at: Option<String>,
    /// When our scanner noticed, ISO-8601; null on mirror-only rows. Tooltip only.
    pub detected_at: Option<String>,
    /// Aggregate rating 0-10, or null only when the work has NO rating anywhere: our own
    /// readers' review average where they have rated it, else MangaDex's community rating
    /// from the statistics cache (`work_stats`, migration 0106). Resolved per page (20
    /// rows, two batched queries), not materialized: both move independently of the feed.
    ///
    /// The MERGED number, kept for a reader that predates the two below and can print one
    /// star only. It cannot say whose rating it is, so a current reader uses the two below.
    pub rating: Option<f64>,
    /// Our own readers' review average, or null when none of them rated the work.
    pub reader_rating: Option<f64>,
    /// MangaDex's community rating, or null when it has none or the admin turned
    /// MangaDex ratings off (`show_mangadex_ratings`).
    pub mangadex_rating: Option<f64>,
    pub is_nsfw: bool,
}

/// A page of the merged Updates feed — the same four-field envelope as `SeriesPage`.
#[derive(SimpleObject, Clone)]
pub struct UpdateFeedPage {
    pub items: Vec<UpdateFeedRow>,
    pub page: i32,
    pub has_next_page: bool,
    pub total: Option<i32>,
}

/// DB row shape of `feed_series_updates` (migration 0064). Not a GraphQL type — the
/// resolver maps it to `UpdateFeedRow`, resolving the cover fallback (which needs runtime
/// Suwayomi config) and converting `released_at` back to ISO-8601.
#[derive(sqlx::FromRow)]
struct FeedSeriesUpdateRow {
    #[sqlx(try_from = "crate::db_types::DbString")]
    work_id: String,
    #[sqlx(try_from = "crate::db_types::DbString")]
    reader_id: String,
    #[sqlx(try_from = "crate::db_types::DbString")]
    title: String,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    cover_url: Option<String>,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    suwayomi_thumbnail: Option<String>,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    comic_type: Option<String>,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    status: Option<String>,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    latest_chapter: Option<String>,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    latest_chapter_title: Option<String>,
    #[sqlx(try_from = "crate::db_types::DbOptionalI64")]
    chapter_count: Option<i64>,
    #[sqlx(try_from = "crate::db_types::DbI64")]
    released_at: i64,
    /// Nullable in the struct though migration 0099 leaves no NULLs behind, because a row
    /// INSERTed by a rebuild between the `DELETE` and `default_announced_at` is momentarily
    /// NULL and this type must be able to read it rather than fail the whole page.
    #[sqlx(try_from = "crate::db_types::DbOptionalI64")]
    announced_at: Option<i64>,
    #[sqlx(try_from = "crate::db_types::DbOptionalString")]
    detected_at: Option<String>,
    is_nsfw: bool,
}

/// Epoch milliseconds → ISO-8601 UTC, for a column that is only numeric because the two
/// clocks it merges are stored in incompatible TEXT encodings (see migration 0064).
///
/// An out-of-range value yields the epoch rather than panicking: this is a display
/// timestamp on a cache row, and a corrupt one must not take down the whole feed.
fn epoch_ms_to_iso(ms: i64) -> String {
    crate::db_types::format_date(
        chrono::DateTime::from_timestamp_millis(ms).unwrap_or_else(|| {
            chrono::DateTime::from_timestamp_millis(0).expect("epoch is in range")
        }),
    )
}

