    #[tokio::test]
    async fn record_view_counts_anonymously_and_surfaces_on_series() {
        // Views are the popularity signal: `recordView` needs NO auth (anonymous reads
        // count too), and the count surfaces on `series.views` across all windows. Here
        // a cached numeric series is viewed three times by an anonymous client (no
        // token), then read back.
        let (s, pool) = setup_full(100).await;
        sqlx::query(
            "INSERT INTO suwayomi_series (id, title, status, source_id, chapter_count, updated_at) \
             VALUES (777, 'Viewed Series', 'ONGOING', 'src', 0, '2020-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();

        for _ in 0..3 {
            let r = exec(
                &s,
                r#"mutation { recordView(seriesId: "777") }"#,
                None,
                "9.9.9.9",
            )
            .await;
            assert!(r.errors.is_empty(), "recordView failed: {:?}", r.errors);
            assert_eq!(
                r.data.into_json().unwrap()["recordView"],
                serde_json::json!(true)
            );
        }

        let r = exec(
            &s,
            r#"{ series(id: "777") { views { total last7d last24h } } }"#,
            None,
            "9.9.9.9",
        )
        .await;
        assert!(r.errors.is_empty(), "series query failed: {:?}", r.errors);
        let v = r.data.into_json().unwrap()["series"]["views"].clone();
        assert_eq!(v["total"], serde_json::json!(3));
        assert_eq!(v["last24h"], serde_json::json!(3));
        assert_eq!(v["last7d"], serde_json::json!(3));
    }

    #[tokio::test]
    async fn record_view_admin_is_silent_others_still_count() {
        // Admin-silent-reads gate (write-side, in `record_view`): an admin viewer's
        // `recordView` must leave `series_views`/`series_view_bucket` untouched, while
        // an anonymous caller and an ordinary signed-in caller both still increment.
        // Asserted on the actual table rows, not the mutation's `true` return — `true`
        // is exactly what the skip path also returns, so that alone would pass even if
        // the gate were deleted.
        let (s, pool) = setup_full(100).await;
        sqlx::query(
            "INSERT INTO suwayomi_series (id, title, status, source_id, chapter_count, updated_at) \
             VALUES (778, 'Admin-Silent Series', 'ONGOING', 'src', 0, '2020-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();

        async fn total_and_bucket(pool: &Database) -> (i64, i64) {
            let total: Option<i64> = crate::db_types::query_scalar(
                "SELECT total FROM series_views WHERE series_key = '778'",
            )
            .fetch_optional(pool)
            .await
            .unwrap();
            let bucket: i64 = crate::db_types::query_scalar(
                "SELECT COALESCE(SUM(views), 0)::bigint FROM series_view_bucket WHERE series_key = '778'",
            )
            .fetch_one(pool)
            .await
            .unwrap();
            (total.unwrap_or(0), bucket)
        }

        // Three admin reads: no `series_views` row, no bucket write.
        for _ in 0..3 {
            let r = exec(
                &s,
                r#"mutation { recordView(seriesId: "778") }"#,
                Some("admintok"),
                "9.9.9.9",
            )
            .await;
            assert!(
                r.errors.is_empty(),
                "recordView (admin) failed: {:?}",
                r.errors
            );
            assert_eq!(
                r.data.into_json().unwrap()["recordView"],
                serde_json::json!(true),
                "the mutation still reports success on the admin skip path"
            );
        }
        let (total, bucket) = total_and_bucket(&pool).await;
        assert_eq!(total, 0, "admin reads must not create a series_views row");
        assert_eq!(bucket, 0, "admin reads must not write series_view_bucket");

        // Anonymous read: increments both tables.
        let r = exec(
            &s,
            r#"mutation { recordView(seriesId: "778") }"#,
            None,
            "9.9.9.9",
        )
        .await;
        assert!(
            r.errors.is_empty(),
            "recordView (anon) failed: {:?}",
            r.errors
        );
        let (total, bucket) = total_and_bucket(&pool).await;
        assert_eq!(total, 1, "anonymous read must increment series_views");
        assert_eq!(
            bucket, 1,
            "anonymous read must increment series_view_bucket"
        );

        // Ordinary signed-in read (bob, is_admin = FALSE): also increments.
        let r = exec(
            &s,
            r#"mutation { recordView(seriesId: "778") }"#,
            Some("bobtok"),
            "9.9.9.9",
        )
        .await;
        assert!(
            r.errors.is_empty(),
            "recordView (bob) failed: {:?}",
            r.errors
        );
        let (total, bucket) = total_and_bucket(&pool).await;
        assert_eq!(
            total, 2,
            "ordinary signed-in read must increment series_views"
        );
        assert_eq!(
            bucket, 2,
            "ordinary signed-in read must increment series_view_bucket"
        );
    }

    fn data_json(resp: &async_graphql::Response) -> String {
        serde_json::to_string(&resp.data).unwrap()
    }

    #[tokio::test]
    async fn set_show_nsfw_persists_and_requires_auth() {
        let s = setup().await;
        // Default is hidden.
        let r = exec(
            &s,
            r#"{ session { user { showNsfw } } }"#,
            Some("bobtok"),
            "1.1.1.1",
        )
        .await;
        assert!(data_json(&r).contains("\"showNsfw\":false"));
        // Toggle on.
        let r = exec(
            &s,
            r#"mutation { setShowNsfw(value: true) }"#,
            Some("bobtok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "unexpected: {:?}", r.errors);
        let r = exec(
            &s,
            r#"{ session { user { showNsfw } } }"#,
            Some("bobtok"),
            "1.1.1.1",
        )
        .await;
        assert!(data_json(&r).contains("\"showNsfw\":true"));
        // Anonymous cannot set it.
        let r = exec(
            &s,
            r#"mutation { setShowNsfw(value: true) }"#,
            None,
            "1.1.1.1",
        )
        .await;
        assert_eq!(first_error(&r), "Not authenticated");
    }

    #[tokio::test]
    async fn update_profile_persists_and_is_reflected_in_session() {
        let s = setup().await;
        // Fresh account: display name/bio are null, joinedAt is present.
        let r = exec(
            &s,
            r#"{ session { user { displayName bio joinedAt } } }"#,
            Some("bobtok"),
            "1.1.1.1",
        )
        .await;
        let j = data_json(&r);
        assert!(j.contains("\"displayName\":null"), "unexpected: {j}");
        assert!(j.contains("\"bio\":null"), "unexpected: {j}");
        assert!(j.contains("\"joinedAt\":\"2020-01-01"), "unexpected: {j}");

        // Update both; the mutation returns the refreshed user.
        let r = exec(
            &s,
            r#"mutation { updateProfile(input: { displayName: "  Bob the Reader  ", bio: "I read manga." }) { displayName bio } }"#,
            Some("bobtok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "unexpected: {:?}", r.errors);
        let j = data_json(&r);
        assert!(
            j.contains("\"displayName\":\"Bob the Reader\""),
            "trimmed: {j}"
        );
        assert!(j.contains("\"bio\":\"I read manga.\""), "{j}");

        // A blank display name clears it (falls back to username in the UI).
        let r = exec(
            &s,
            r#"mutation { updateProfile(input: { displayName: "   ", bio: "still here" }) { displayName bio } }"#,
            Some("bobtok"),
            "1.1.1.1",
        )
        .await;
        assert!(data_json(&r).contains("\"displayName\":null"), "cleared");

        // Anonymous cannot update.
        let r = exec(
            &s,
            r#"mutation { updateProfile(input: { bio: "x" }) { bio } }"#,
            None,
            "1.1.1.1",
        )
        .await;
        assert_eq!(first_error(&r), "Not authenticated");
    }

