    #[tokio::test]
    async fn introspection_toggles_with_flag() {
        let pool = TestPoolOptions::new()
            .max_connections(1)
            .connect("sqlite::memory:")
            .await
            .unwrap();
        sqlx::migrate!("./migrations_pg")
            .run(pool.write())
            .await
            .unwrap();
        let cover_dir = crate::cover_store::test_support::TestDir::new();
        let mk_state = || async {
            std::sync::Arc::new(AppState {
                pool: pool.clone(),
                cover_pool: crate::cover_store::test_support::store(&cover_dir),
                suwayomi: crate::suwayomi::SuwayomiClient::new(
                    "http://127.0.0.1:1".into(),
                    None,
                    None,
                ),
                mangadex: std::sync::Arc::new(crate::mangadex::MangaDexClient::new(
                    "test-ua", 5.0, 40.0,
                )),
                admin_users: vec![],
                scan_health: Mutex::new(ScanHealth::default()),
                auth_limiter: RateLimiter::new(100, 60),
                comment_limiter: comment_limiter(),
                rating_limiter: rating_limiter(),
                password_work: std::sync::Arc::new(tokio::sync::Semaphore::new(4)),
                federated_limiter: RateLimiter::new(100, 60),
                session_ttl_secs: 30 * 24 * 60 * 60,
                series_inflight: KeyedLocks::default(),
                chapters_inflight: KeyedLocks::default(),
                source_budgets: Default::default(),
                catalogue_cover_phash: false,
                ext_icons_dir: std::path::PathBuf::new(),
                media_manifests: None,
                policy: Default::default(),
                setup_code: crate::instance::SetupCode::default(),
            })
        };
        const Q: &str = "{ __schema { queryType { name } } }";
        // Disabled (production default): `__schema` resolves to null, so the API
        // surface is not enumerable.
        let disabled = build_schema(mk_state().await, true);
        let r = disabled.execute(Q).await;
        assert_eq!(
            serde_json::to_string(&r.data).unwrap(),
            "{\"__schema\":null}",
            "disabled introspection must not leak the schema (errors: {:?})",
            r.errors
        );
        // Enabled (dev): introspection returns the real schema.
        let enabled = build_schema(mk_state().await, false);
        let r = enabled.execute(Q).await;
        let json = serde_json::to_string(&r.data).unwrap();
        assert!(
            r.errors.is_empty() && json.contains("queryType") && json != "{\"__schema\":null}",
            "introspection should work when enabled: {json} (errors: {:?})",
            r.errors
        );
    }

    #[tokio::test]
    async fn provision_admins_creates_promotes_and_is_idempotent() {
        let pool = TestPoolOptions::new()
            .max_connections(1)
            .connect("sqlite::memory:")
            .await
            .unwrap();
        sqlx::migrate!("./migrations_pg")
            .run(pool.write())
            .await
            .unwrap();

        // Missing admin + password → created as admin with the configured email.
        provision_admins(&pool, &["admin".into()], Some("s3cret-pw"), Some("a@b.com"))
            .await
            .unwrap();
        let (is_admin, email, hash): (i64, String, String) = crate::db_types::query_tuple(
            "SELECT is_admin, email, password_hash FROM users WHERE username='admin'",
        )
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(is_admin, 1);
        assert_eq!(email, "a@b.com");
        assert!(auth::verify_password("s3cret-pw", &hash), "password usable");

        // Idempotent re-run with a different password: no duplicate, existing
        // password preserved (never re-passworded).
        provision_admins(
            &pool,
            &["admin".into()],
            Some("different-pw"),
            Some("a@b.com"),
        )
        .await
        .unwrap();
        let (count,): (i64,) =
            crate::db_types::query_tuple("SELECT COUNT(*) FROM users WHERE username='admin'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(count, 1, "no duplicate admin row");
        let (hash2,): (String,) =
            crate::db_types::query_tuple("SELECT password_hash FROM users WHERE username='admin'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert!(
            auth::verify_password("s3cret-pw", &hash2),
            "existing password preserved, not reset"
        );

        // Existing non-admin requires proof of its current password.
        seed_user(&pool, "ca19534e-7e0c-4aa3-8f2d-6a3799b9c33c", "bob", 0, 0).await;
        provision_admins(&pool, &["bob".into()], None, None)
            .await
            .unwrap();
        let (bob_admin,): (i64,) =
            crate::db_types::query_tuple("SELECT is_admin FROM users WHERE username='bob'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(
            bob_admin, 0,
            "a configured name alone cannot grant privileges"
        );
        provision_admins(&pool, &["BOB".into()], Some("wrong-password"), None)
            .await
            .unwrap();
        let (before_proof,): (i64,) = crate::db_types::query_tuple(
            "SELECT is_admin FROM users WHERE id = 'ca19534e-7e0c-4aa3-8f2d-6a3799b9c33c'",
        )
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(before_proof, 0, "wrong password cannot promote");
        let token = new_session(
            &pool,
            "ca19534e-7e0c-4aa3-8f2d-6a3799b9c33c",
            30 * 24 * 60 * 60,
        )
        .await
        .unwrap();
        provision_admins(&pool, &["BOB".into()], Some("password123"), None)
            .await
            .unwrap();
        let (bob_admin, hash): (i64, String) =
            crate::db_types::query_tuple("SELECT is_admin, password_hash FROM users WHERE id = 'ca19534e-7e0c-4aa3-8f2d-6a3799b9c33c'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(bob_admin, 1, "current password proves account ownership");
        assert!(auth::verify_password("password123", &hash));
        let (sessions,): (i64,) =
            crate::db_types::query_tuple("SELECT COUNT(*) FROM sessions WHERE token = $1")
                .bind(auth::hash_token(&token))
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(sessions, 0, "pre-promotion sessions are revoked atomically");
    }

    #[tokio::test]
    async fn provisioning_refuses_suspended_and_ambiguous_accounts() {
        let (_, pool) = setup_full(100).await;
        seed_user(
            &pool,
            "6e9ed78f-5182-408b-a07d-51c90dc2f031",
            "suspended",
            0,
            1,
        )
        .await;
        provision_admins(&pool, &["suspended".into()], Some("password123"), None)
            .await
            .unwrap();
        let (privileged,): (i64,) = crate::db_types::query_tuple(
            "SELECT is_admin FROM users WHERE id = '6e9ed78f-5182-408b-a07d-51c90dc2f031'",
        )
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(privileged, 0);
        // Model a collision predating the guard migration, without merging IDs.
        sqlx::query("DROP INDEX users_username_ascii_unique")
            .execute(&pool)
            .await
            .unwrap();
        seed_user(&pool, "legacy-a", "legacy", 0, 0).await;
        // Only usernames are ambiguous; the email guard remains in force.
        sqlx::query(r#"UPDATE users SET email='legacy-a@example.com' WHERE id='a7e2d6fe-4528-488c-8878-6710cfda56b2'"#)
            .execute(&pool)
            .await
            .unwrap();
        seed_user(&pool, "legacy-b", "LEGACY", 0, 0).await;
        provision_admins(&pool, &["legacy".into()], Some("password123"), None)
            .await
            .unwrap();
        let (privileged,): (i64,) = crate::db_types::query_tuple(
            "SELECT SUM(CASE WHEN is_admin THEN 1 ELSE 0 END) FROM users WHERE translate(username, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') = 'legacy'",
        )
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(privileged, 0, "no arbitrary legacy identity promoted");
    }

    #[tokio::test]
    async fn admin_session_lifetime_is_bounded_and_respects_shorter_setting() {
        let (_, pool) = setup_full(100).await;
        seed_user(&pool, "session-admin", "session-admin", 1, 0).await;
        seed_user(&pool, "session-reader", "session-reader", 0, 0).await;
        for (id, configured, expected) in [
            ("session-admin", 30 * 24 * 60 * 60, 8 * 60 * 60),
            ("session-admin", 120, 120),
            ("session-reader", 30 * 24 * 60 * 60, 30 * 24 * 60 * 60),
        ] {
            let token = new_session(
                &pool,
                &crate::db_types::test_uuid(id).to_string(),
                configured,
            )
            .await
            .unwrap();
            let (created, expires): (String, String) = crate::db_types::query_tuple(
                "SELECT created_at, expires_at FROM sessions WHERE token = $1",
            )
            .bind(auth::hash_token(&token))
            .fetch_one(&pool)
            .await
            .unwrap();
            let elapsed = chrono::DateTime::parse_from_rfc3339(&expires).unwrap()
                - chrono::DateTime::parse_from_rfc3339(&created).unwrap();
            // Expiry serialization truncates fractional seconds; the duration
            // must remain within one second of the selected lifetime.
            assert!(elapsed.num_milliseconds() <= expected * 1000);
            assert!(elapsed.num_milliseconds() > (expected - 1) * 1000);
        }
    }

    #[tokio::test]
    async fn admin_session_slides_on_use_up_to_its_upper_limit() {
        let (schema, pool) = setup_full(100).await;
        seed_user(&pool, "slide-admin", "slide-admin", 1, 0).await;
        seed_user(&pool, "slide-reader", "slide-reader", 0, 0).await;
        let ttl = 30 * 24 * 60 * 60;
        let admin = new_session(
            &pool,
            &crate::db_types::test_uuid("slide-admin").to_string(),
            ttl,
        )
        .await
        .unwrap();
        let reader = new_session(
            &pool,
            &crate::db_types::test_uuid("slide-reader").to_string(),
            ttl,
        )
        .await
        .unwrap();
        // Seconds from now to the session's end, after one request with its token.
        let remaining_after_use = |token: String, signed_in_ago: i64, ends_in: i64| {
            let (schema, pool) = (&schema, &pool);
            async move {
                sqlx::query(
                    "UPDATE sessions SET created_at = now() - make_interval(secs => $2), \
                     expires_at = now() + make_interval(secs => $3) WHERE token = $1",
                )
                .bind(auth::hash_token(&token))
                .bind(signed_in_ago as f64)
                .bind(ends_in as f64)
                .execute(pool)
                .await
                .unwrap();
                let r = exec(
                    schema,
                    "{ session { user { username } } }",
                    Some(&token),
                    "198.51.100.7",
                )
                .await;
                assert!(r.errors.is_empty(), "{:?}", r.errors);
                let left: f64 = crate::db_types::query_scalar(
                    "SELECT EXTRACT(EPOCH FROM expires_at - now())::float8 FROM sessions WHERE token = $1",
                )
                .bind(auth::hash_token(&token))
                .fetch_one(pool)
                .await
                .unwrap();
                left as i64
            }
        };
        let idle = auth::ADMIN_IDLE_SECS;
        // Used an hour before its end: the end moves to a full idle period from now.
        let left = remaining_after_use(admin.clone(), 7 * 3600, 3600).await;
        assert!((idle - 5..=idle).contains(&left), "slid to {left}s");
        // Used again right away: no write, the end stays where it is.
        let left = remaining_after_use(admin.clone(), 7 * 3600, idle - 60).await;
        assert!(
            (idle - 65..=idle - 55).contains(&left),
            "rewrote to {left}s"
        );
        // Near the upper limit: the end stops at sign-in plus the limit.
        let left = remaining_after_use(admin.clone(), auth::ADMIN_MAX_SECS - 1800, 600).await;
        assert!((1795..=1800).contains(&left), "capped at {left}s");
        // A reader's session does not slide.
        let left = remaining_after_use(reader, 3600, 3600).await;
        assert!((3595..=3600).contains(&left), "reader moved to {left}s");
        // An expired admin session is not revived.
        let r = {
            sqlx::query(
                "UPDATE sessions SET expires_at = now() - interval '1 second' WHERE token = $1",
            )
            .bind(auth::hash_token(&admin))
            .execute(&pool)
            .await
            .unwrap();
            exec(
                &schema,
                "{ session { user { username } } }",
                Some(&admin),
                "198.51.100.7",
            )
            .await
        };
        assert_eq!(
            r.data.into_json().unwrap()["session"],
            serde_json::Value::Null
        );
    }

